require_once __DIR__.'/inc/bootstrap.php';require_once __DIR__.'/inc/legal_center.php';require_login();$pdo=db();$cu=current_user();$adminId=tickex_admin_id($cu);if(!tickex_is_super_admin($cu))abort_404('No tenés permiso.');tickex_legal_ensure_schema($pdo);$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){if(!tickex_csrf_verify(isset($_POST['_csrf'])?(string)$_POST['_csrf']:''))$error='La sesión venció. Actualizá la página.';else try{$action=isset($_POST['action'])?(string)$_POST['action']:'';if($action==='document'){tickex_legal_save_document($pdo,$_POST['document_type'],$_POST['title'],$_POST['summary'],$_POST['body'],!empty($_POST['publish']),$adminId);flash('ok',!empty($_POST['publish'])?'Nueva versión publicada.':'Borrador guardado.');}elseif($action==='withdrawal'){tickex_legal_update_withdrawal($pdo,(int)$_POST['request_id'],(string)$_POST['status'],$_POST['resolution_note'],$adminId);flash('ok','Solicitud actualizada.');}elseif($action==='privacy'){tickex_legal_update_privacy_request($pdo,(int)$_POST['request_id'],(string)$_POST['status'],$_POST['resolution_note'],$adminId);flash('ok','Solicitud de datos actualizada.');}header('Location: superadmin_legales.php');exit;}catch(Exception $e){$error=$e->getMessage();}}
$types=tickex_legal_types();$all=tickex_legal_documents($pdo,true);$latest=array();foreach($all as $doc)if(!isset($latest[$doc['document_type']]))$latest[$doc['document_type']]=$doc;$requests=tickex_legal_withdrawals($pdo);$privacyRequests=tickex_legal_privacy_requests($pdo);$csrf=tickex_csrf_token();$flashes=flash_get_all();$title='Legales y consentimientos';include __DIR__.'/inc/layout_top.php';
?><style>.legal-admin{max-width:1180px;margin:0 auto;display:grid;gap:16px}.la-hero{padding:29px;background:radial-gradient(circle at 90% 0,rgba(70,216,239,.15),transparent 29%),linear-gradient(135deg,#171b38,#35226e)}.la-kicker{color:#5edbef;text-transform:uppercase;letter-spacing:.13em;font-size:11px;font-weight:900}.la-hero h1{margin:6px 0;font-size:clamp(32px,5vw,48px);letter-spacing:-.04em}.la-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}.la-doc{border:1px solid var(--line);border-radius:14px;padding:16px}.la-doc-head{display:flex;justify-content:space-between;gap:10px}.la-doc h3{margin:4px 0}.la-state{height:max-content;border:1px solid var(--line);border-radius:999px;padding:5px 8px;font-size:10px;text-transform:uppercase}.la-doc form{display:grid;gap:9px;margin-top:12px}.la-doc textarea[name=body]{min-height:260px}.la-actions{display:flex;gap:8px;flex-wrap:wrap}.la-request{display:grid;grid-template-columns:minmax(0,1fr) 150px minmax(180px,.8fr) auto;gap:9px;align-items:end;padding:13px;border:1px solid var(--line);border-radius:13px}.la-request strong,.la-request small{display:block}.la-request small{color:var(--muted)}@media(max-width:850px){.la-grid{grid-template-columns:1fr}.la-request{grid-template-columns:1fr 1fr}}@media(max-width:520px){.la-request{grid-template-columns:1fr}}</style>
<main class="legal-admin"><section class="card la-hero"><div class="la-kicker">Cumplimiento y transparencia</div><h1>Legales y consentimientos</h1><p class="muted">Versioná documentos públicos y atendé solicitudes de consumidores con trazabilidad.</p></section><?php foreach($flashes as $f):?><div class="flash <?php echo e($f['type']);?>"><?php echo e($f['msg']);?></div><?php endforeach;?><?php if($error):?><div class="flash err"><?php echo e($error);?></div><?php endif;?><section class="card"><div class="la-kicker">Documentación</div><h2>Versiones editables</h2><p class="muted">Los textos iniciales son borradores técnicos. Completá los datos legales y hacelos revisar antes de publicar.</p><div class="la-grid"><?php foreach($types as $type=>$label):$doc=isset($latest[$type])?$latest[$type]:array('version'=>0,'title'=>$label,'summary'=>'','body'=>'','status'=>'draft');?><article class="la-doc"><div class="la-doc-head"><div><div class="la-kicker">Versión <?php echo (int)$doc['version'];?></div><h3><?php echo e($label);?></h3></div><span class="la-state"><?php echo e($doc['status']);?></span></div><details><summary>Editar y crear nueva versión</summary><form method="post"><input type="hidden" name="_csrf" value="<?php echo e($csrf);?>"><input type="hidden" name="action" value="document"><input type="hidden" name="document_type" value="<?php echo e($type);?>"><label>Título<input name="title" value="<?php echo e($doc['title']);?>" required></label><label>Resumen<textarea name="summary" rows="3"><?php echo e($doc['summary']);?></textarea></label><label>Contenido<textarea name="body" required><?php echo e($doc['body']);?></textarea></label><div class="la-actions"><button class="btn secondary" type="submit">Guardar borrador</button><button class="btn" type="submit" name="publish" value="1" onclick="return confirm('¿Publicar esta nueva versión? La versión vigente anterior quedará archivada.');">Publicar versión</button><?php if($type!=='organizers'):?><a class="btn secondary" href="legal.php?doc=<?php echo e($type);?>" target="_blank">Ver página pública</a><?php endif;?></div></form></details></article><?php endforeach;?></div></section><section class="card"><div class="la-kicker">Consumidores</div><h2>Solicitudes de arrepentimiento</h2><?php if(!$requests):?><p class="muted">Todavía no hay solicitudes.</p><?php else:?><div style="display:grid;gap:9px"><?php foreach($requests as $request):?><form method="post" class="la-request"><input type="hidden" name="_csrf" value="<?php echo e($csrf);?>"><input type="hidden" name="action" value="withdrawal"><input type="hidden" name="request_id" value="<?php echo (int)$request['id'];?>"><div><strong><?php echo e($request['public_id']);?> · <?php echo e($request['full_name']);?></strong><small><?php echo e($request['email']);?> · <?php echo e($request['purchase_reference']);?><?php echo $request['event_name']?' · '.e($request['event_name']):'';?></small></div><label>Estado<select name="status"><?php foreach(array('received'=>'Recibida','reviewing'=>'En revisión','approved'=>'Aprobada','rejected'=>'Rechazada','refunded'=>'Reembolsada') as $key=>$value):?><option value="<?php echo e($key);?>"<?php echo $request['status']===$key?' selected':'';?>><?php echo e($value);?></option><?php endforeach;?></select></label><label>Resolución<input name="resolution_note" value="<?php echo e($request['resolution_note']);?>"></label><button class="btn secondary" type="submit">Actualizar</button></form><?php endforeach;?></div><?php endif;?></section><section class="card"><div class="la-kicker">Privacidad</div><h2>Solicitudes sobre datos personales</h2><?php if(!$privacyRequests):?><p class="muted">Todavía no hay solicitudes.</p><?php else:?><div style="display:grid;gap:9px"><?php foreach($privacyRequests as $request):?><form method="post" class="la-request"><input type="hidden" name="_csrf" value="<?php echo e($csrf);?>"><input type="hidden" name="action" value="privacy"><input type="hidden" name="request_id" value="<?php echo (int)$request['id'];?>"><div><strong><?php echo e($request['public_id']);?> · <?php echo e($request['full_name']);?></strong><small><?php echo e($request['email']);?> · <?php echo e($request['request_type']);?><?php echo $request['details']?' · '.e($request['details']):'';?></small></div><label>Estado<select name="status"><?php foreach(array('received'=>'Recibida','reviewing'=>'En revisión','completed'=>'Completada','rejected'=>'Rechazada') as $key=>$value):?><option value="<?php echo e($key);?>"<?php echo $request['status']===$key?' selected':'';?>><?php echo e($value);?></option><?php endforeach;?></select></label><label>Resolución<input name="resolution_note" value="<?php echo e($request['resolution_note']);?>"></label><button class="btn secondary" type="submit">Actualizar</button></form><?php endforeach;?></div><?php endif;?></section></main><?php include __DIR__.'/inc/layout_bottom.php';?>
